import 'dart:convert';
import 'dart:io';
import 'package:dio/dio.dart';
import 'package:flutter/material.dart';
import '../models/app_constants.dart';
import '../models/repair_models.dart';
import 'dio_client.dart';

class RepairException implements Exception { final String message; const RepairException(this.message); @override String toString()=>message; }
class RepairService {
  RepairService({Dio? dio, Future<bool> Function()? reauthenticate}) : _dio = dio, _reauthenticate = reauthenticate;
  final Dio? _dio; final Future<bool> Function()? _reauthenticate; bool _ready=false; String _uid='';
  Future<Dio> get client async { if (_dio != null) return _dio!; await DioClient().initialize(); return DioClient().dio; }
  static const catalogs = <RepairCatalog>[
    RepairCatalog(id:'5bbbaf0a-b7b7-11eb-b305-4bcc6b2984af', title:'后勤报修', subtitle:'宿舍、公共设施与生活服务', department:'后勤保障中心', processId:'4e2cc26d-08b4-4cab-a3a7-fba23a23e11d', color:Color(0xFFE8843A), icon:Icons.home_repair_service_outlined),
    RepairCatalog(id:'b4435ca0-99f6-11ec-bf7a-177427586306', title:'校园网络报修', subtitle:'无线网络、网线与校园网故障', department:'信息与网络中心', processId:'d86a31ef-6e54-4da5-8c8f-a881986ec422', color:Color(0xFF478BEA), icon:Icons.wifi_tethering_error_rounded),
    RepairCatalog(id:'f11e3e78-9ace-11ec-9f07-f7b2f4ca88d7', title:'一校通报修', subtitle:'一卡通、数字校园与信息化设备', department:'信息与网络中心', processId:'aa21a42a-a2f7-48a7-aae6-fc374e4ebc44', color:Color(0xFFDD5B75), icon:Icons.devices_other_outlined),
    RepairCatalog(id:'ffa62964-9539-11ec-a409-0f7763ad71f7', title:'业务系统报修', subtitle:'教务、门户及其他业务系统', department:'信息与网络中心', processId:'f83a50f6-95f9-41d9-bf27-851f340035a4', color:Color(0xFF38A88D), icon:Icons.apps_outlined),
  ];
  Future<void> _ensure() async { if (_ready) return; final d=await client; try { final identity=await _rpcRaw(d,'/v2/login/isAuthenticated',null); if (identity is Map && identity['id'] != null) {_uid='${identity['id']}'; _ready=true; return;} } catch (_) {} await _exchange(d); final identity=await _rpcRaw(d,'/v2/login/isAuthenticated',null); if (identity is Map && identity['id'] != null) {_uid='${identity['id']}'; _ready=true; return;} if (_reauthenticate != null && await _reauthenticate!()) { await _exchange(d); final refreshed=await _rpcRaw(d,'/v2/login/isAuthenticated',null); if (refreshed is Map && refreshed['id'] != null) {_uid='${refreshed['id']}'; _ready=true; return;} } throw const RepairException('报修平台登录凭证交换失败，请重新登录'); }
  Future<void> _exchange(Dio d) async { var u=Uri.parse(AppConstants.repairsSsoUrl); for(var i=0;i<8;i++){ final r=await d.getUri(u, options:Options(followRedirects:false, validateStatus:(s)=>s!=null&&s<500)); final loc=r.headers.value(HttpHeaders.locationHeader); if(loc==null||loc.isEmpty) break; var n=u.resolve(loc); if(n.host=='bxpt.hunau.edu.cn'&&n.scheme=='http') n=n.replace(scheme:'https'); if(n==u) break; u=n; } }
  Future<dynamic> _rpcRaw(Dio d,String path,dynamic params) async { final r=await d.post('${AppConstants.repairsBaseUrl}/relax/mobile/rpc', queryParameters:{'p':path,'t':DateTime.now().millisecondsSinceEpoch}, data:{'jsonrpc':'2.0','method':path,'id':'1','params':params}, options:Options(contentType:Headers.jsonContentType,responseType:ResponseType.plain,headers:{'Origin':AppConstants.repairsBaseUrl,'Referer':'${AppConstants.repairsBaseUrl}/relax/mobile/index.html','X-Requested-With':'XMLHttpRequest'})); dynamic b=r.data; if(b is String){try{b=jsonDecode(b);}catch(_){}} if(b is! Map) throw const RepairException('报修平台暂时不可用'); if(b['error']!=null) throw RepairException('${b['error']}'); return b['result']; }
  Future<dynamic> _rpc(String path,dynamic params) async { await _ensure(); return _rpcRaw(await client,path,params); }
  Future<List<RepairOrder>> fetchOrders({bool ongoing=true,bool isDraft=false}) async { final method=ongoing?'/v2/service/portal/workorderData/ongoingPage':'/v2/service/portal/workorderData/finishPage'; final result=await _rpc(method,['37ea4a70-af77-4c1a-9422-7582afc0de41',{'attributes':['id','type','code','service_catalog','apply_user','apply_description','flow_status','create_time','start_time','process','node_name','close_time','dynamic_title'],'filter':{'attribute':{'and':[{'simple':{'name':'apply_user','operator':'eq','value':_uid}}]},'query':''},'orders':[{'name':'start_time','type':'desc'}],'pageSize':'50','pageIndex':'1'}]); final data=result is Map?result['data']:null; return data is List ? data.whereType<Map>().map((e)=>RepairOrder.fromJson(e.cast<String,dynamic>())).toList():[]; }
  Future<RepairOrder> fetchDetail(RepairOrder order) async { final type=order.raw['type'] is Map?'${(order.raw['type'] as Map)['id']??''}':'${order.raw['type']??''}'; Map<String,dynamic> detail={}; try{final r=await _rpc('/v2/workorder/data/getById',[type,order.id]); if(r is Map) detail=r.cast<String,dynamic>();}catch(_){} return RepairOrder.fromJson({...order.raw,...detail}, logs: const [], attachments: const [], actions: const []); }
  Future<void> submit({required RepairCatalog catalog, required String title, required String description, required String location, String phone=''}) async { final id=await _rpc('/v2/cmdb/ci/id',[]); final node=await _rpc('/v2/workorder/orderConfig/getNodeByServiceCatalog',[catalog.id]); final form={'id':'$id','type':catalog.processId,'source':'mobile','service_catalog':catalog.id,'dynamic_title':title.trim(),'wtmsh':description.trim(),'bchshm':location.trim(),'lxfs':phone.trim(),'apply_user':_uid}; final action=await _rpc('/v2/workorder/action/list',[node,'$id']); final actionId=action is List&&action.isNotEmpty?'${(action.first as Map)['id']??''}':''; if(actionId.isEmpty) throw const RepairException('未找到报修提交动作'); final result=await _rpc('/v2/workorder/action/executeWithValidate',[actionId,[{'id':'$id','type':catalog.processId,'node':'$node'},form,{'service_catalog':catalog.id}],[]]); if(result is! Map||result['state']!=true) throw const RepairException('提交失败，请检查内容后重试'); }
}
